text:
Here's your water tracker. Tap a glass or the + button each time you drink, and it resets every day. It saves on this device if your browser allows it.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
body{font-family:Segoe UI,sans-serif;max-width:360px;margin:24px auto;padding:0 16px;text-align:center;color:#1b2a33}
h1{font-size:20px;margin:0 0 4px}
.count{font-size:44px;font-weight:600;margin:12px 0 4px}
.msg{height:20px;color:#2a7f62;font-size:14px}
.bar{height:10px;background:#e3eef3;border-radius:5px;overflow:hidden;margin:12px 0 20px}
.fill{height:100%;width:0;background:#2b8fc7;transition:width .3s}
.glasses{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:20px}
.g{height:56px;border:2px solid #2b8fc7;border-radius:6px 6px 14px 14px;background:#fff;font-size:22px;cursor:pointer}
.g.on{background:#2b8fc7;color:#fff}
.row button{font-size:16px;padding:8px 18px;margin:0 4px;border-radius:8px;border:1px solid #2b8fc7;background:#fff;color:#1b2a33;cursor:pointer}
.row .main{background:#2b8fc7;color:#fff}
.week{display:flex;justify-content:space-between;align-items:flex-end;height:70px;margin-top:28px}
.col{flex:1;margin:0 3px;font-size:11px}
.col div{background:#9ccbe4;border-radius:3px 3px 0 0;margin-bottom:3px}
.col.today div{background:#2b8fc7}
</style>
</head>
<body>
<h1>Water today</h1>
<div class="count"><span id="n">0</span> / 8</div>
<div class="msg" id="msg"></div>
<div class="bar"><div class="fill" id="fill"></div></div>
<div class="glasses" id="glasses"></div>
<div class="row">
<button onclick="change(-1)">−</button>
<button class="main" onclick="change(1)">+ Add a glass</button>
<button onclick="reset()">Reset</button>
</div>
<div class="week" id="week"></div>
<script>
var GOAL=8,data={};
try{data=JSON.parse(localStorage.getItem("water")||"{}")}catch(e){}
function key(d){return d.toISOString().slice(0,10)}
var today=key(new Date());
function save(){try{localStorage.setItem("water",JSON.stringify(data))}catch(e){}}
function get(k){return data[k]||0}
function change(d){data[today]=Math.max(0,Math.min(20,get(today)+d));save();draw()}
function set(i){data[today]=(get(today)===i+1)?i:i+1;save();draw()}
function reset(){data[today]=0;save();draw()}
function draw(){
var c=get(today);
document.getElementById("n").textContent=c;
document.getElementById("fill").style.width=Math.min(100,c/GOAL*100)+"%";
document.getElementById("msg").textContent=c>=GOAL?"Goal reached. Well done!":(GOAL-c)+" more to go";
var g=document.getElementById("glasses");g.innerHTML="";
for(var i=0;i<GOAL;i++){var b=document.createElement("button");b.className="g"+(i<c?" on":"");b.textContent=i<c?"💧":"";(function(i){b.onclick=function(){set(i)}})(i);g.appendChild(b)}
var w=document.getElementById("week");w.innerHTML="";
for(var j=6;j>=0;j--){var dt=new Date();dt.setDate(dt.getDate()-j);var k=key(dt),v=get(k);
var col=document.createElement("div");col.className="col"+(j==0?" today":"");
var bar=document.createElement("div");bar.style.height=Math.min(50,v/GOAL*50)+"px";
col.appendChild(bar);col.appendChild(document.createTextNode(["S","M","T","W","T","F","S"][dt.getDay()]));
w.appendChild(col)}
}
draw();
</script>
</body>
</html>
